export function price(user, items) {
  let total = 0;
  if (items) {
    for (const it of items) {
      if (it && it.price) {
        if (user && user.vip) {
          if (it.price > 100) total += it.price * 0.8;
          else total += it.price * 0.9;
        } else {
          if (it.onSale) total += it.price * 0.95;
          else total += it.price;
        }
      }
    }
  }
  return total;
}

